import { Buffer } from "node:buffer";
export const CHANGELOG_MARKER =
  "<!-- changelog-main: generated by changelog.yml -->";
const BODY_LIMIT = 125_000;

function shortenUtf8(text, maxBytes) {
  let bytes = 0,
    result = "";
  for (const character of text) {
    const size = Buffer.byteLength(character, "utf8");
    if (bytes + size > maxBytes) break;
    result += character;
    bytes += size;
  }
  return result;
}

export function buildChangelog({ log, url, sha, base }) {
  const prefix = `${CHANGELOG_MARKER}\n\n## Changes\n\n`;
  const history = base
    ? `[Full diff](${url}/compare/${base}...${sha})`
    : `[Full history](${url}/commits/${sha})`;
  const lines = log.split("\n");
  const footer = (omitted) =>
    `\n\n${omitted ? `${omitted} older entries omitted. ` : ""}${history}`;
  // Reserving the largest possible omission count keeps every entry complete.
  const budget =
    BODY_LIMIT - Buffer.byteLength(prefix + footer(lines.length), "utf8");
  const kept = [];
  let bytes = 0;
  for (let index = lines.length - 1; index >= 0; index--) {
    const separator = lines[index].indexOf("\t");
    const hash = lines[index].slice(0, separator),
      title = lines[index].slice(separator + 1);
    const link = ` ([${hash.slice(0, 7)}](${url}/commit/${hash}))`;
    let entry = `- ${title}${link}`;
    if (!kept.length && Buffer.byteLength(entry) > budget) {
      entry = `- ${shortenUtf8(title, budget - Buffer.byteLength(`- …${link}`))}…${link}`;
    }
    const size = Buffer.byteLength(entry) + (kept.length ? 1 : 0);
    if (bytes + size > budget) break;
    kept.push(entry);
    bytes += size;
  }
  return (
    prefix + kept.reverse().join("\n") + footer(lines.length - kept.length)
  );
}

export async function generateDraftChangelog({ github, context, exec, core }) {
  const repo = context.repo;
  const marker = CHANGELOG_MARKER;
  const releases = await github.paginate(github.rest.repos.listReleases, {
    ...repo,
    per_page: 100,
  });
  const draft = releases.find(
    (release) => release.draft && release.body?.includes(marker),
  );
  const latest = releases
    .filter((release) => !release.draft && !release.prerelease)
    .sort((a, b) => Date.parse(b.published_at) - Date.parse(a.published_at))[0];
  const git = async (args) =>
    (
      await exec.getExecOutput("git", args, {
        silent: true,
      })
    ).stdout.trim();
  const sha = await git(["rev-parse", "HEAD"]);
  let base;
  if (latest) {
    base = await git([
      "rev-parse",
      "--verify",
      `refs/tags/${latest.tag_name}^{commit}`,
    ]);
    const ancestry = await exec.getExecOutput(
      "git",
      ["merge-base", "--is-ancestor", base, sha],
      { silent: true, ignoreReturnCode: true },
    );
    if (ancestry.exitCode !== 0) {
      throw new Error(
        `Published release ${latest.tag_name} is not an ancestor of main.`,
      );
    }
  }

  // Include direct commits and merged branch commits, including the
  // initial commit when there is no published release yet.
  const args = ["log", "--no-merges", "--reverse", "--format=%H%x09%s", sha];
  if (base) args.push(`^${base}`);
  const log = await git(args);
  if (!log) {
    if (draft) {
      const current = await github.rest.repos.getRelease({
        ...repo,
        release_id: draft.id,
      });
      if (!current.data.draft) {
        throw new Error(
          "The draft was published during this run; rerun to use the new baseline.",
        );
      }
      if (!current.data.body?.includes(CHANGELOG_MARKER)) {
        throw new Error("The draft is no longer generated; rerun to preserve manual notes.");
      }
      await github.rest.repos.deleteRelease({ ...repo, release_id: draft.id });
    }
    core.info("No unreleased commits; removed any generated draft.");
    return;
  }
  const url = `${context.serverUrl}/${repo.owner}/${repo.repo}`;
  const body = buildChangelog({ log, url, sha, base });
  const changes = log.split("\n");
  const release = {
    ...repo,
    tag_name: draft?.tag_name ?? `changelog-draft-${context.runId}`,
    target_commitish: sha,
    name: draft?.name ?? "Next release",
    body,
    draft: true,
    prerelease: false,
  };
  if (draft) {
    const current = await github.rest.repos.getRelease({
      ...repo,
      release_id: draft.id,
    });
    if (!current.data.draft) {
      throw new Error(
        "The draft was published during this run; rerun to use the new baseline.",
      );
    }
    if (!current.data.body?.includes(CHANGELOG_MARKER)) {
      throw new Error("The draft is no longer generated; rerun to preserve manual notes.");
    }
  }
  const result = draft
    ? await github.rest.repos.updateRelease({
        ...release,
        release_id: draft.id,
      })
    : await github.rest.repos.createRelease(release);
  await core.summary
    .addLink("Review draft changelog", result.data.html_url)
    .addRaw(`\n\nIncludes ${changes.length} commits through ${sha}.`)
    .write();
}
